190	static ssize_t sf32lb_nand_read(FAR struct mtd_dev_s *dev, off_t offset,
191	                                size_t nbytes, FAR uint8_t *buffer)
192	{
193	  FAR struct sf32lb_nand_dev_s *priv = (FAR struct sf32lb_nand_dev_s *)dev;
194	  FAR FLASH_HandleTypeDef *handle = priv->handle;
195	  uint32_t page_size = priv->page_size;
196	  uint32_t page_addr;
197	  uint32_t page_off;
198	  uint32_t chunk;
199	  int ret;
200	
201	  if (offset < 0 || buffer == NULL || nbytes == 0)
202	    {
203	      return -EINVAL;
204	    }
205	
206	  sf32lb_nand_lock();
207	
208	  while (nbytes > 0)
209	    {
210	      page_addr = (uint32_t)offset / page_size * page_size;
211	      page_off = (uint32_t)offset % page_size;
212	      chunk = page_size - page_off;
213	      if (chunk > nbytes)
214	        {
215	          chunk = nbytes;
216	        }
217	
218	      ret = HAL_NAND_READ_PAGE(handle, page_addr, buffer, chunk);
219	      if (ret <= 0)
220	        {
221	          syslog(LOG_ERR,
222	                 "ERROR: NAND read failed: addr=0x%08lx ret=%d\n",
223	                 (unsigned long)page_addr, ret);
