225	          return -EIO;
226	        }
227	
228	      offset += chunk;
229	      buffer += chunk;
230	      nbytes -= chunk;
231	    }
232	
233	  sf32lb_nand_unlock();
234	  return (ssize_t)(nbytes == 0 ? 0 : -EIO);  /* unreachable if loop completes */
