527	/****************************************************************************
528	 * Name: BSP_Board_PreInit
529	 *
530	 * Description:
531	 *   Board pre-init for nxboot bootloader.
532	 *   Configures clocks (XT48, DLL1/2/3), flash clocks, and PSRAM clocks.
533	 *   Based on the main board's bsp_init.c but simplified for bootloader use.
534	 *
535	 ****************************************************************************/
536	
537	void BSP_Board_PreInit(void)
538	{
539	  /* Enable XT48 oscillator */
540	  HAL_HPAON_EnableXT48();
541	
542	  /* Select system clock to HXT48 (48 MHz) */
543	  HAL_RCC_HCPU_ClockSelect(RCC_CLK_MOD_SYS, RCC_SYSCLK_HXT48);
544	  HAL_RCC_HCPU_ClockSelect(RCC_CLK_MOD_HP_PERI, RCC_CLK_PERI_HXT48);
545	
546	  if (PM_STANDBY_BOOT != SystemPowerOnModeGet())
547	    {
548	      /* Halt LCPU first to avoid LCPU in running state */
549	      HAL_HPAON_WakeCore(CORE_ID_LCPU);
550	      HAL_RCC_Reset_and_Halt_LCPU(1);
551	
552	      /* Enable DLL1 at 240 MHz for system clock */
553	      HAL_PMU_EnableDLL(1);
554	      HAL_PMU_SWITCH_VRET_LOWER();
555	      HAL_HPAON_StartGTimer();
556	
557	      /* Configure LCPU clocks */
558	      HAL_RCC_LCPU_ClockSelect(RCC_CLK_MOD_LP_PERI, RCC_CLK_PERI_HXT48);
559	      HAL_LPAON_EnableXT48();
560	      HAL_RCC_LCPU_ClockSelect(RCC_CLK_MOD_SYS, RCC_SYSCLK_HXT48);
561	      HAL_RCC_LCPU_SetDiv(1, 1, 3);
562	    }
563	
564	  __HAL_SYSCFG_HPBG_EN();
565	  __HAL_SYSCFG_HPBG_VDDPSW_EN();
566	
567	  /* Enable DLL1 at 240 MHz and select as system clock */
568	  HAL_RCC_HCPU_EnableDLL1(240000000);
569	  HAL_RCC_HCPU_ClockSelect(RCC_CLK_MOD_SYS, RCC_SYSCLK_DLL1);
570	
571	  /* Reset sysclk used by HAL_Delay_us */
572	  HAL_Delay_us(0);
573	
574	  /* Set flash dividers */
575	  mpi1_div = 1;
576	  mpi2_div = 1;
577	  mpi3_div = 3;
578	  mpi4_div = 3;
579	  mpi5_div = 1;
580	
581	  /* Init the low level hardware (pinmux, power) */
582	  HAL_MspInit();
583	
584	  if (mpi3_div <= 4)
585	    {
586	      HAL_QSPI_SET_RXDELAY(2, 1, 0);
587	    }
588	
589	  /* Enable DLL2 (288 MHz) for PSRAM, DLL3 (216 MHz) for flash */
590	  HAL_RCC_HCPU_EnableDLL2(288000000);
591	  HAL_RCC_HCPU_EnableDLL3(216000000);
592	  HAL_RCC_HCPU_ClockSelect(RCC_CLK_MOD_FLASH3, RCC_CLK_FLASH_DLL3);
593	  HAL_RCC_HCPU_ClockSelect(RCC_CLK_MOD_FLASH4, RCC_CLK_FLASH_DLL3);
594	
595	#ifdef BSP_USING_PSRAM
596	  HAL_RCC_HCPU_ClockSelect(RCC_CLK_MOD_FLASH1, RCC_CLK_FLASH_DLL2);
597	  HAL_RCC_HCPU_ClockSelect(RCC_CLK_MOD_FLASH2, RCC_CLK_FLASH_DLL2);
598	#endif
599	
600	  /* Set system clock dividers */
