static int sf32lb_nand_register_partitions(FAR struct sf32lb_nand_dev_s *wdev)
{
  /* Partition table (SBUS addresses) */

  static const uint32_t part_offsets[] =
    {
      HCPU_MPI_SBUS_ADDR(FLASH4_BASE_ADDR),
      HCPU_MPI_SBUS_ADDR(FLASH4_BASE_ADDR) + 0x00800000,
      HCPU_MPI_SBUS_ADDR(FLASH4_BASE_ADDR) + 0x01000000,
    };

  static const uint32_t part_sizes[] =
    {
      0x00800000,
      0x00800000,
      0x00800000,
    };

  static const char *devnames[] =
    {
      "/dev/ota0",
      "/dev/ota1",
      "/dev/ota2",
    };

  int i;
  int ret;

  for (i = 0; i < 3; i++)
    {
      off_t startblock =
        (off_t)((part_offsets[i] - nand_flash_sbus_base) /
                wdev->block_size);
      size_t nblocks =
        (size_t)(part_sizes[i] / wdev->block_size);

      FAR struct mtd_dev_s *part =
        mtd_partition(&wdev->mtd, startblock, nblocks);
      if (part == NULL)
        {
          syslog(LOG_ERR,
                 "ERROR: mtd_partition(%s, blk=%lu, n=%lu) failed\n",
                 devnames[i],
                 (unsigned long)startblock,
                 (unsigned long)nblocks);
          continue;
        }

      ret = register_mtddriver(devnames[i], part, 0755, part);
      if (ret < 0)
        {
          syslog(LOG_ERR,
                 "ERROR: register_mtddriver(%s) failed: %d\n",
                 devnames[i], ret);
        }
      else
        {
          syslog(LOG_INFO,
                 "INFO: NAND partition %s registered (offset=0x%08lx "
                 "size=0x%08lx)\n",
                 devnames[i],
                 (unsigned long)part_offsets[i],
                 (unsigned long)part_sizes[i]);
        }
    }

  return OK;
}

